sys_script_include.script:
var BedStateMachine = Class.create();

BedStateMachine.STATUS = {
    AVAILABLE: '1',
    RESERVED: '2',
    OCCUPIED: '3',
    UNDER_CLEANING: '4',
    UNDER_MAINTENANCE: '5',
    BLOCKED: '6',
    OUT_OF_SERVICE: '7'
};

BedStateMachine.STATUS_LABELS = {
    '1': 'Available',
    '2': 'Reserved',
    '3': 'Occupied',
    '4': 'Under Cleaning',
    '5': 'Under Maintenance',
    '6': 'Blocked',
    '7': 'Out of Service'
};

BedStateMachine.prototype = {
    initialize: function() {},

    getStatusLabel: function(statusValue) {
        return BedStateMachine.STATUS_LABELS[String(statusValue)] || String(statusValue);
    },

    isValidTransition: function(fromStatus, toStatus) {
        if (!fromStatus || !toStatus) return false;
        if (String(fromStatus) === String(toStatus)) return true;

        var transitions = {
            '1': ['2', '3', '5', '6', '7'], // Available -> Reserved, Occupied, Maintenance, Blocked, Out of Service
            '2': ['1', '3', '6'],           // Reserved -> Available, Occupied, Blocked
            '3': ['4'],                		// Occupied -> Under Cleaning
            '4': ['1', '5', '6'],           // Under Cleaning -> Available, Maintenance, Blocked
            '5': ['1', '4', '7'],           // Under Maintenance -> Available, Cleaning, Out of Service
            '6': ['4', '5'],           		// Blocked -> Cleaning, Maintenance
            '7': ['4', '5']                 // Out of Service -> Cleaning, Maintenance 
        };

        var allowed = transitions[String(fromStatus)];
        return allowed ? allowed.indexOf(String(toStatus)) !== -1 : true;
    },

    /**
     * Transitions a bed record to a new status and logs to bed_status_log.
     * @param {GlideRecord|String} bed - Bed GlideRecord or sys_id
     * @param {String} toStatus - New status value ('1'-'7')
     * @param {String} reason - Reason for transition
     * @param {GlideRecord|String} [admission] - Optional admission record or sys_id
     * @returns {Object} { success: Boolean, message: String }
     */
    transition: function(bed, toStatus, reason, admission) {
        var bedGr;
        if (typeof bed === 'string') {
            bedGr = new GlideRecord('x_2223823_apollo_0_beds');
            if (!bedGr.get(bed)) {
                return { success: false, message: 'Bed record not found.' };
            }
        } else {
            bedGr = bed;
        }

        var fromStatus = bedGr.getValue('status');
        var hospital = bedGr.getValue('hospital');
        var admissionId = '';
        if (admission) {
            admissionId = (typeof admission === 'string') ? admission : admission.getUniqueValue();
        }

        if (!this.isValidTransition(fromStatus, toStatus)) {
            return {
                success: false,
                message: 'Invalid bed transition from ' + this.getStatusLabel(fromStatus) + ' to ' + this.getStatusLabel(toStatus) + '.'
            };
        }

        bedGr.setValue('status', toStatus);
        if (bedGr.isValidField('current_admission')) {
            if (toStatus === BedStateMachine.STATUS.OCCUPIED) {
                bedGr.setValue('current_admission', admissionId);
            } else {
                bedGr.setValue('current_admission', '');
            }
        }
        var bedUpdated = bedGr.update();
        if (!bedUpdated) {
            return { success: false, message: 'Failed to update bed status.' };
        }

        this.writeStatusLog(bedGr.getUniqueValue(), hospital, fromStatus, toStatus, reason);

        return {
            success: true,
            message: 'Bed status successfully transitioned to ' + this.getStatusLabel(toStatus) + '.'
        };
    },

    /**
     * Writes a row to x_2223823_apollo_0_bed_status_log.
     */
    writeStatusLog: function(bedId, hospitalId, fromStatus, toStatus, reason) {
        try {
            var logGr = new GlideRecord('x_2223823_apollo_0_bed_status_log');
            logGr.initialize();
            logGr.setValue('bed', bedId);
            if (hospitalId) {
                logGr.setValue('hospital', hospitalId);
            }
            logGr.setValue('from_status', fromStatus);
            logGr.setValue('to_status', toStatus);
            logGr.setValue('changed_by', gs.getUserID());
            logGr.setValue('changed_at', new GlideDateTime());
            logGr.setValue('reason', reason || ('Status changed to ' + this.getStatusLabel(toStatus)));
            logGr.insert();
        } catch (e) {
            gs.error('BedStateMachine: Failed to write bed status log: ' + e.message);
        }
    },

    type: 'BedStateMachine'
};
